_map:
if (item.train_id && item.lng != null && item.lat != null) {
emit(item.train_id, {
  lng: item.lng,
  lat: item.lat,
  delay: item.delay || 0,
  _ts: item._ts || 0
});
}

_reduce:
var best = values[0], i, v;
for (i = 1; i < values.length; i++) {
  v = values[i];
  if ((v._ts || 0) > (best._ts || 0)) {
    best = v;
  }
}
emit(best);

_finalize:
var cells = {}, row, d, gx, gy, key, c, out = [];
reduction.forEach(function (row) {
  if (!row || row.length < 2 || !row[1]) {
    return;
  }
  d = row[1];
  if (d.lng == null || d.lat == null) {
    return;
  }
  gx = Math.floor(d.lng * 400);
  gy = Math.floor(d.lat * 400);
  key = gx + ',' + gy;
  if (!cells[key]) {
    cells[key] = {
      lng: (gx + 0.5) / 400,
      lat: (gy + 0.5) / 400,
      delaySum: 0,
      count: 0,
      maxDelay: 0
    };
  }
  c = cells[key];
  c.delaySum += d.delay || 0;
  c.count += 1;
  c.maxDelay = Math.max(c.maxDelay, d.delay || 0);
});
Object.keys(cells).forEach(function (k) {
  c = cells[k];
  c.avgDelay = c.count ? c.delaySum / c.count : 0;
  out.push([k, c]);
});
emit(out);
